def parse_grid_section(text, label):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n',text)
    h,w=map(int,m.groups()); tail=text[m.end():]
    rows=[]
    for ln in tail.splitlines():
        vals=[int(x) for x in ln.split() if x.isdigit()]
        if len(vals)==w:
            rows.append(vals)
            if len(rows)==h: break
        elif rows: break
    assert len(rows)==h,(label,len(rows),h)
    return rows
